// api/_lib/gh-logo-asset.js
// The real Greenwich Handyman Co. logo mark, cropped/padded/resized from
// the source the user provided (Downloads/'GH CO LOGO.png'), base64-inlined
// rather than read from a file on disk -- the safest way to ship a binary
// asset into a Vercel serverless function bundle without relying on the
// build tracing an fs.readFileSync() path correctly.
// 480x378 PNG, transparent background, ~58KB decoded.
export const GH_LOGO_PNG_BASE64 = '';
export const GH_LOGO_WIDTH = 480;
export const GH_LOGO_HEIGHT = 378;
